function saudar(nome, saudacao = 'Olá') {
  return `${saudacao}, ${nome}!`;
}

function somarTodos(...numeros) {
  let total = 0;
  for (const n of numeros) {
    total += n;
  }
  return total;
}

console.log(saudar('Ana'));           // Olá, Ana!  (default)
console.log(saudar('Ana', 'Bom dia')); // Bom dia, Ana!

console.log(somarTodos(1, 2, 3));    // 6
console.log(somarTodos());           // 0  (array vazio)
console.log(somarTodos(...[4, 5]));  // 9  (spread abre o array)

// Passos 1 e 2: cliente fixo, cupom com default e itens via rest.
function montarResumo(cliente, cupom = 'SEM-CUPOM', ...itens) {
  // Passo 3: validações antes de montar a frase.
  if (typeof cliente !== 'string') {
    throw new Error('cliente precisa ser texto');
  }
  if (itens.length === 0) {
    throw new Error('nenhum item informado');
  }

  // Passos 4 e 5: junta os itens e devolve o resumo pronto.
  return `${cliente} (cupom ${cupom}): ${itens.join(', ')}`;
}

console.log(montarResumo('Ana', 'NOVO10', 'curso', 'livro'));
// Ana (cupom NOVO10): curso, livro

console.log(montarResumo('Bia', 'curso', 'livro', 'caneta'));
// Bia (cupom SEM-CUPOM): curso, livro, caneta
